import { escapeHtml, numericValue, METRICS } from './health-metrics.mjs?v=health-comparison-20261106-v12';
const HEIGHT = 280;
const GOLD = '#f59e0b';
const DEFAULT_YEARS = [2021, 2022, 2023, 2024, 2025];
const decimal = new Intl.NumberFormat('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
const CHART_UNITS = { million_sar: { unit: 'مليار ريال', factor: 1 / 1000 }, million_shares: { unit: 'مليون سهم', factor: 1 }, sar: { unit: 'ريال', factor: 1 }, percent: { unit: '%', factor: 100 } };
const DEFINITIONS = METRICS.filter(metric => ['revenue','grossIncome','operatingIncome','netProfit'].includes(metric.key)).map(metric => ({ key: metric.key, title: metric.label, group: 'ملخص النتائج المالية', ...(metric.unit === 'sar' ? CHART_UNITS.sar : metric.unit === 'percent' ? CHART_UNITS.percent : metric.unit === 'million_shares' ? CHART_UNITS.million_shares : CHART_UNITS.million_sar) }));
const clamp = (value, min, max) => Math.min(max, Math.max(min, value));
const plotWidth = width => Math.max(300, Math.round(numericValue(width) > 0 ? width : 600));
const coordinate = value => String(Number(value.toFixed(4)));
const modelsForYear = (companies, year) => DEFINITIONS.map(definition => ({ ...definition, year, series: (companies ?? []).map((company, index) => { const record=(company.years??[]).find(item=>item.period==='FY' && item.year===year); const rawValue=numericValue(record?.values?.[definition.key]); return { key:String(company.symbol), title:company.name??String(company.symbol), color: index % 2 ? '#fbbf24' : GOLD, points:[{ category:company.name??String(company.symbol), rawValue, value:rawValue===null?null:rawValue*definition.factor }] }; }) }));
export function getComparisonModels(companies, year) { return modelsForYear(companies, year); }
export function getChartOptions(companies, years=DEFAULT_YEARS) { return DEFINITIONS.map(definition=>({key:definition.key,label:definition.title,group:definition.group,available:true})); }
function niceQuantum(target) { const safe=target>0?target:1; const power=10**Math.floor(Math.log10(safe)); const normalized=safe/power; return [1,2,2.5,5,10].find(value=>value>=normalized)*power; }
function chartAxis(model) { const values=model.series.flatMap(series=>series.points.map(point=>point.value)).filter(value=>value!==null); const low=Math.min(0,...values), high=Math.max(0,...values); const paddedLow=low<0?low*1.2:0, paddedHigh=high>0?high*1.2:(low===0?1:0); const step=niceQuantum((paddedHigh-paddedLow)/5); const min=Math.floor(paddedLow/step)*step, max=Math.ceil(paddedHigh/step)*step, intervals=Math.max(1,Math.round((max-min)/step)); return {min,max,step,ticks:Array.from({length:intervals+1},(_,i)=>min+i*step)}; }
function tickLabel(value,axis) { const places=Math.min(8,Math.max(0,-Math.floor(Math.log10(axis.step))+1)); return Number(value.toFixed(places)).toLocaleString('en-US',{maximumFractionDigits:places}); }
function pointTitle(model,series,point) { if(point.value===null) return `${series.title} · ${model.year}: غير متاح (—)`; const display=decimal.format(point.value); const original=model.unit==='مليار ريال'?`؛ الأصل: ${decimal.format(point.rawValue)} مليون ريال`:''; return `${series.title} · ${model.year}: ${display} ${model.unit}${original}`; }
export function renderChartSvg(model,width=600) { const W=plotWidth(width),axis=chartAxis(model),axisLabels=axis.ticks.map(value=>tickLabel(value,axis)); const left=Math.max(46,...axisLabels.map(label=>label.length*6.6+12)),right=16,top=36,bottom=236,plotHeight=bottom-top,scale=value=>bottom-(value-axis.min)/(axis.max-axis.min)*plotHeight,zero=scale(0); const count=Math.max(1,model.series.length),groupWidth=(W-left-right)/count,barWidth=clamp(groupWidth*0.62,18,70); const description=`${model.title} — ${model.year} — مقارنة الشركات`; const grid=axis.ticks.map((value,index)=>{const y=coordinate(scale(value));return `<g class="chart-axis-tick"><line class="chart-grid" x1="${coordinate(left)}" x2="${W-right}" y1="${y}" y2="${y}" stroke="var(--line, #2a333e)" stroke-width="1"/><text class="chart-axis-label" x="${coordinate(left-8)}" y="${coordinate(scale(value)+4)}" text-anchor="end" fill="var(--muted, #98a4b3)">${escapeHtml(axisLabels[index])}</text></g>`;}).join(''); const bars=[],labels=[],names=[]; model.series.forEach((series,index)=>{const point=series.points[0],center=left+groupWidth*(index+0.5),x=center-barWidth/2,title=escapeHtml(pointTitle(model,series,point)),attrs=`data-company="${escapeHtml(series.key)}" data-value="${point.rawValue===null?'null':escapeHtml(point.rawValue)}"`; if(point.value===null) labels.push(`<text class="chart-value chart-missing" ${attrs} x="${coordinate(center)}" y="${coordinate(zero-8)}" text-anchor="middle" fill="var(--muted, #98a4b3)" aria-label="${title}">—<title>${title}</title></text>`); else {const endpoint=scale(point.value),y=Math.min(zero,endpoint),height=Math.abs(endpoint-zero);bars.push(`<rect class="chart-bar" ${attrs} data-chart-value="${escapeHtml(point.value)}" x="${coordinate(x)}" y="${coordinate(y)}" width="${coordinate(barWidth)}" height="${coordinate(height)}" fill="${series.color}" aria-label="${title}"><title>${title}</title></rect>`); const label=decimal.format(point.value),labelY=clamp(point.value<0?endpoint+16:y-8,12,HEIGHT-28); labels.push(`<text class="chart-value" ${attrs} x="${coordinate(center)}" y="${coordinate(labelY)}" text-anchor="middle" fill="var(--ink, #f1f5f9)" aria-label="${title}">${escapeHtml(label)}<title>${title}</title></text>`);} names.push(`<text class="chart-year" x="${coordinate(center)}" y="260" text-anchor="middle" fill="var(--muted, #98a4b3)">${escapeHtml(series.title)}</text>`);}); return `<svg xmlns="http://www.w3.org/2000/svg" class="bank-chart-svg" width="${W}" height="${HEIGHT}" viewBox="0 0 ${W} ${HEIGHT}" role="img" aria-label="${escapeHtml(description)}" data-axis-min="${escapeHtml(axis.min)}" data-axis-max="${escapeHtml(axis.max)}" data-axis-step="${escapeHtml(axis.step)}" data-zero-y="${coordinate(zero)}" style="width:100%;height:280px;display:block;font-family:inherit;font-size:12px;direction:ltr"><title>${escapeHtml(description)}</title><g font-family="inherit" font-size="12" direction="ltr" style="unicode-bidi:isolate">${grid}<line class="chart-zero-baseline" x1="${coordinate(left)}" x2="${W-right}" y1="${coordinate(zero)}" y2="${coordinate(zero)}" stroke="var(--muted, #98a4b3)" stroke-width="1.3"/>${bars.join('')}${labels.join('')}${names.join('')}</g></svg>`; }
const signature=model=>JSON.stringify(model);
export function renderHealthCharts(companies,year) { return getComparisonModels(companies,year).map(model=>`<article class="bank-chart-card" data-chart-key="${escapeHtml(model.key)}" dir="rtl"><h4>${escapeHtml(model.title)}</h4><p class="bank-chart-unit">${escapeHtml(model.unit)} · ${escapeHtml(year)}</p><div class="bank-chart-canvas" data-chart-canvas="${escapeHtml(model.key)}" data-plot-width="600" data-plot-year="${escapeHtml(year)}" data-plot-signature="${escapeHtml(signature(model))}">${renderChartSvg(model)}</div></article>`).join(''); }
export function fitHealthCharts(container,companies,year) { if(!container?.querySelectorAll)return; const models=new Map(getComparisonModels(companies,year).map(model=>[model.key,model])); for(const canvas of container.querySelectorAll('[data-chart-canvas]')){const model=models.get(canvas.dataset.chartCanvas);if(!model)continue;const width=plotWidth(canvas.clientWidth),sig=signature(model);if(canvas.dataset.plotWidth===String(width)&&canvas.dataset.plotYear===String(year)&&canvas.dataset.plotSignature===sig)continue;const svg=canvas.querySelector('svg');if(svg)svg.outerHTML=renderChartSvg(model,width);canvas.dataset.plotWidth=String(width);canvas.dataset.plotYear=String(year);canvas.dataset.plotSignature=sig;} }
